package erratum

import "errors"

// Use opens a resource via opener, calls Frob(input) on it, and ensures the
// resource is closed exactly once in all cases.
//
// Transient errors from the opener are retried; any other error is returned.
// A panic from Frob is recovered: if it is a FrobError, Defrob is called with
// the error's defrobTag before the resource is closed, and the error is
// returned from Use.
func Use(opener ResourceOpener, input string) error {
	var r Resource
	var err error
	for {
		r, err = opener()
		if err == nil {
			break
		}
		var transient TransientError
		if errors.As(err, &transient) {
			continue
		}
		return err
	}

	defer r.Close()
	defer func() {
		if p := recover(); p != nil {
			var fe FrobError
			if errors.As(p, &fe) {
				r.Defrob(fe.defrobTag)
			}
			err = p.(error)
		}
	}()

	r.Frob(input)
	return err
}

